from django.db import migrations, models

ACTIONS = ("create", "update", "delete")
# Mirrors seed_permissions templates: Admin/Prod. Manager get no *.delete.
ROLE_GRANTS = {
    "super-admin": ACTIONS,
    "admin": ("create", "update"),
    "production-manager": ("create", "update"),
}


def add_bank_holiday_permissions(apps, schema_editor):
    """Bank holidays were Super Admin only; keep those users working without a re-seed."""
    Permission = apps.get_model("accounts", "Permission")
    Role = apps.get_model("accounts", "Role")
    RolePermission = apps.get_model("accounts", "RolePermission")
    UserRole = apps.get_model("accounts", "UserRole")

    perms = {}
    for action in ACTIONS:
        perms[action], _ = Permission.objects.get_or_create(
            module="bank_holiday",
            action=action,
            defaults={"code": f"bank_holiday.{action}"},
        )

    user_ids = set()
    for slug, actions in ROLE_GRANTS.items():
        role = Role.objects.filter(slug=slug).first()
        if role is None:
            continue
        for action in actions:
            RolePermission.objects.get_or_create(role=role, permission=perms[action])
        user_ids.update(UserRole.objects.filter(role=role).values_list("user_id", flat=True))

    from apps.accounts.services.permission_cache import invalidate_user_permissions

    for user_id in user_ids:
        invalidate_user_permissions(user_id)


def remove_bank_holiday_permissions(apps, schema_editor):
    Permission = apps.get_model("accounts", "Permission")
    Permission.objects.filter(module="bank_holiday").delete()


